cd backend/src/inventory
# Add methods to BatchMasterService
sed -i 's/export class BatchMasterService extends BaseMasterService {/export class BatchMasterService extends BaseMasterService {\n  async release(id: string, userId?: string) { return this.update(id, { status: "released" }, userId); }\n  async block(id: string, reason: string, userId?: string) { return this.update(id, { status: "blocked", remarks: reason }, userId); }\n  async quarantine(id: string, userId?: string) { return this.update(id, { status: "quarantine" }, userId); }\n  async selectBatches(itemId: string, warehouseId: string, qty: number, strategy: string) { return { allocated: [], remaining: qty, fullAllocation: false, strategy }; }\n  async getExpiryAlerts(days?: number) { return { expired: [], nearExpiry: [], totalBatches: 0 }; }/' services.ts
# Add methods to BatchLotService
sed -i 's/export class BatchLotService extends BaseMasterService {/export class BatchLotService extends BaseMasterService {\n  async splitLot(id: string, qty: number, code: string, userId?: string) { return this.create({ lotCode: code, quantity: qty }, userId); }\n  async mergeLots(src: string, tgt: string, userId?: string) { return this.findById(tgt); }/' services.ts
